create table bots(id serial primary key,name text,channel_ids int[] default '{}',trigger jsonb default '{"type":"first"}',graph jsonb default '{"nodes":[],"edges":[]}',active bool default true,runs int default 0,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table bot_runs(id serial primary key,bot_id int references bots on delete cascade,conversation_id int references conversations on delete cascade,node text,waiting bool default false,vars jsonb default '{}',tries int default 0,status text default 'active',updated_at timestamptz default now(),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table subscriptions(id serial primary key,contact_id int references contacts,description text,amount numeric not null,due_day int not null default 10,start_date date default current_date,end_date date,provider text,rules jsonb,active bool default true,student_id int,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table charges(id serial primary key,subscription_id int references subscriptions on delete cascade,contact_id int references contacts,description text,amount numeric,due_date date,status text default 'pendente',ext_id text,link text,sent jsonb default '[]',paid_at timestamptz,unique(subscription_id,due_date),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table courses(id serial primary key,name text,description text,image_url text,price numeric,lessons_total int default 0,minutes int default 50,active bool default true,data jsonb default '{}',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table students(id serial primary key,contact_id int references contacts,course_id int references courses,teacher text,total_lessons int default 0,status text default 'ativo',notes text,created_at timestamptz default now(),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table lessons(id serial primary key,student_id int references students on delete cascade,starts_at timestamptz not null,minutes int default 50,teacher text,room text,status text default 'agendada',notes text,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table menu_categories(id serial primary key,name text,pos int default 0,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table menu_items(id serial primary key,category_id int references menu_categories,name text,description text,image_url text,price numeric default 0,variants jsonb default '[]',addons jsonb default '[]',active bool default true,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table delivery_zones(id serial primary key,name text,fee numeric default 0,min_order numeric default 0,active bool default true,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table print_jobs(id serial primary key,order_id int references orders on delete cascade,data text,printed bool default false,created_at timestamptz default now(),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
alter table orders add column number int,add column kind text default 'entrega',add column table_no text,add column customer_name text,add column customer_phone text,add column address text,add column zone text,add column subtotal numeric default 0,add column delivery_fee numeric default 0,add column payment_method text,add column paid bool default false,add column notes text,add column printed bool default false,add column updated_at timestamptz default now();
create unique index orders_num on orders(tenant_id,number);
create unique index bot_runs_active on bot_runs(conversation_id) where status='active';
create index on charges(status,due_date);create index on lessons(starts_at);
do $$ declare t text; begin foreach t in array array['bots','bot_runs','subscriptions','charges','courses','students','lessons','menu_categories','menu_items','delivery_zones','print_jobs'] loop
  execute format('create index if not exists %I on %I(tenant_id)','ix_'||t||'_tenant',t);
  execute format('alter table %I enable row level security',t);execute format('alter table %I force row level security',t);
  execute format($f$create policy tenant_iso on %I using (tenant_id = nullif(current_setting('app.tenant',true),'')::int) with check (tenant_id = nullif(current_setting('app.tenant',true),'')::int)$f$,t);
end loop; end $$;
create trigger fk_guard before insert or update on bot_runs for each row execute function fk_guard('bots','bot_id','conversations','conversation_id');
create trigger fk_guard before insert or update on subscriptions for each row execute function fk_guard('contacts','contact_id');
create trigger fk_guard before insert or update on charges for each row execute function fk_guard('subscriptions','subscription_id','contacts','contact_id');
create trigger fk_guard before insert or update on students for each row execute function fk_guard('contacts','contact_id','courses','course_id');
create trigger fk_guard before insert or update on lessons for each row execute function fk_guard('students','student_id');
create trigger fk_guard before insert or update on menu_items for each row execute function fk_guard('menu_categories','category_id');
create trigger fk_guard before insert or update on print_jobs for each row execute function fk_guard('orders','order_id');
